class PrimeNumbers {
    public static void main(String[] args) {
        int n = 5, count = 0, num = 2;
        while (count < n) {
            boolean prime = true;
            for (int i = 2; i <= num / 2; i++) {
                if (num % i == 0) { prime = false; break; }
            }
            if (prime) { System.out.print(num + " "); count++; }
            num++;
        }
    }
}

