class MultipleTry {
    public static void main(String[] args) {
        try { int a = 10 / 0; }
        catch (ArithmeticException e) { System.out.println("Division error"); }
        try { int[] a = {1, 2}; System.out.println(a[5]); }
        catch (ArrayIndexOutOfBoundsException e) { System.out.println("Array error"); }
    }
}

class NestedTry {
    public static void main(String[] args) {
        try {
            try { int a = 10 / 0; }
            catch (ArithmeticException e) { System.out.println("Inner catch"); }
            int[] x = {1, 2};
            System.out.println(x[5]);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Outer catch");
        }
    }
}

