import java.awt.*;
import java.awt.event.*;
class StringAWT extends Frame implements ActionListener {
    TextField input = new TextField(20);
    Label result = new Label("Result appears here");
    Button button = new Button("Convert to Uppercase");
    StringAWT() {
        setLayout(new FlowLayout());
        add(input); add(button); add(result);
        button.addActionListener(this);
        setSize(350, 150); setVisible(true);
        addWindowListener(new WindowAdapter() {
            public void windowClosing(WindowEvent e) { dispose(); }
        });
    }
    public void actionPerformed(ActionEvent e) {
        result.setText(input.getText().toUpperCase());
    }
    public static void main(String[] args) { new StringAWT(); }
}

